    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There's one way to arrange 0 pots using 0 types
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the DP table
    for sub_type in range(1, n + 1):
        for total_pots in range(1, m + 1):
            for max_pots in range(1, min(total_pots + 1, a[sub_type - 1]) + 1):
                dp[sub_type][total_pots] = (dp[sub_type][total_pots] + dp[sub_type - 1][total_pots - max_pots]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    result = ""
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must only contain alphabetic characters.")

    # Normalize the key to match the length of the ciphertext
    key = key * (len(ciphertext) // len(key)) + key[:len(ciphertext) % len(key)]

    for char in ciphertext:
        if char.isalpha():
            # Determine the shift by current letter in ciphertext minus the key
            shift = ord(char) - ord(key[key.rfind(char)]) + ord('a') if char.islower() else ord(char) - ord(key[key.rfind(char)]) + ord('A')
            # Apply the shift and handle wrapping
            decrypted_char = chr(((shift - ord('a')) % 26) + ord('a')) if char.islower() else chr(((shift - ord('A')) % 26) + ord('A'))
            result += decrypted_char
        else:
            result += char

    return result

