        raise ValueError("Modulus must be nonzero")

    x, y, u, v = 0, 1, 1, 0
    while a != 0:
        q, r = divmod(a, b)
        x, y = u - q * x, v - q * y
        a, b = b, r

    if y < 0:
        y += b

    return y

