    x, y, gcd = 0, 1, b

    while gcd != 1:
        q = gcd // b
        x, y = y, x - q * y
        gcd = b, gcd % b

    if gcd == 1:
        # Make x positive if it's negative
        if x < 0:
            x += b
        return x
    else:
